<?php require_once __DIR__.'/auth.php';require_admin();require_once __DIR__.'/../includes/admin_layout.php';$pdo=db();if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=$pdo->prepare('INSERT INTO departments(name,description,active) VALUES(?,?,1)');$s->execute([trim($_POST['name']),trim($_POST['description']??'')]);flash('Department added.');redirect('departments.php');}$rows=$pdo->query('SELECT * FROM departments ORDER BY name')->fetchAll();admin_header('Departments','departments.php');?><div class="pagehead"><div><h1>Departments</h1><div class="muted">Clinical department directory.</div></div></div><div class="card"><form method="post"><?=csrf_field()?><div class="form-grid"><div class="field"><label>Department name</label><input name="name" required></div><div class="field"><label>Description</label><input name="description"></div></div><button style="margin-top:14px">Add department</button></form></div><div class="grid" style="margin-top:18px"><?php foreach($rows as $r):?><div class="card"><h3><?=e($r['name'])?></h3><p><?=e($r['description'])?></p></div><?php endforeach;?></div><?php admin_footer();
